"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import { useEffect, useLayoutEffect, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** Props for a rotating word. Pass `paused` from a visible pause control when the rotation runs longer than five seconds. */
export interface WordRotateProps {
  words: string[];
  /** Time each word stays, in milliseconds. */
  interval?: number;
  paused?: boolean;
  className?: string;
}

const SWAP: Transition = { type: "spring", stiffness: 380, damping: 39, mass: 1 };
const WIDTH: Transition = { type: "spring", stiffness: 420, damping: 41, mass: 1 };
const FADE: Transition = { duration: 0.2 };
const INSTANT: Transition = { duration: 0 };

/**
 * Cycles one word inside a sentence. The outgoing word rises out as the next
 * rises in, and the gap resizes to fit it. Hovering pauses the rotation.
 */
export function WordRotate({ words, interval = 2400, paused = false, className }: WordRotateProps) {
  const [index, setIndex] = useState(0);
  const [hovered, setHovered] = useState(false);
  const [width, setWidth] = useState<number>();
  const sizers = useRef<(HTMLSpanElement | null)[]>([]);
  const reduceMotion = useReducedMotion();
  // A parent can pass a shorter list mid-rotation, so never read past its end.
  const shown = words.length > 0 ? index % words.length : 0;

  useLayoutEffect(() => {
    const measure = () => setWidth(sizers.current[shown]?.offsetWidth);
    measure();
    // A web font that loads late changes every width, so measure again once fonts settle.
    let active = true;
    void document.fonts?.ready.then(() => {
      if (active) measure();
    });
    return () => {
      active = false;
    };
  }, [shown, words]);

  useEffect(() => {
    if (paused || hovered || words.length < 2) return;
    const timer = window.setInterval(() => setIndex((current) => (current + 1) % words.length), interval);
    return () => window.clearInterval(timer);
  }, [paused, hovered, words.length, interval]);

  // Reduced motion still changes the word, because the words are content, but
  // it cross-fades in place instead of travelling.
  const hidden = reduceMotion ? { opacity: 0 } : { opacity: 0, filter: "blur(4px)" };

  return (
    <span
      className={cn("relative inline-flex", className)}
      onPointerEnter={() => setHovered(true)}
      onPointerLeave={() => setHovered(false)}
    >
      <span className="sr-only">{words.join(", ")}</span>
      <motion.span
        aria-hidden="true"
        initial={false}
        animate={width === undefined ? undefined : { width }}
        transition={reduceMotion ? INSTANT : WIDTH}
        className="relative inline-flex overflow-hidden"
      >
        <AnimatePresence mode="popLayout" initial={false}>
          <motion.span
            key={shown}
            data-word-index={shown}
            initial={{ ...hidden, y: reduceMotion ? 0 : "100%" }}
            animate={{ opacity: 1, filter: "blur(0px)", y: 0 }}
            exit={{ ...hidden, y: reduceMotion ? 0 : "-100%" }}
            transition={reduceMotion ? FADE : SWAP}
            className="inline-block whitespace-nowrap"
          >
            {words[shown]}
          </motion.span>
        </AnimatePresence>
      </motion.span>
      {/* Invisible copies measure each word, so the gap animates to a known width. */}
      <span aria-hidden="true" className="invisible absolute left-0 top-0 flex flex-col">
        {words.map((word, wordIndex) => (
          <span
            key={wordIndex}
            ref={(node) => {
              sizers.current[wordIndex] = node;
            }}
            className="w-max whitespace-nowrap"
          >
            {word}
          </span>
        ))}
      </span>
    </span>
  );
}
